svg.script:

(function() {
  function init() {
    const root = document.getElementById("p8-root");
    if (!root) return;
    if (root.hasAttribute("data-js-initialized")) return;
    root.setAttribute("data-js-initialized", "true");

    const steps = root.querySelectorAll(".p8-trigger");
    const button = root.getElementById("p8-btn-break");

    function setStep(stepVal) {
      root.setAttribute("data-active-step", stepVal);

      const panels = root.querySelectorAll(".p8-panel-content");
      panels.forEach(p => {
        if (p.id === "p8-panel-" + stepVal) {
          p.style.opacity = "1";
          p.style.visibility = "visible";
          p.style.transform = "translateY(0)";
        } else {
          p.style.opacity = "0";
          p.style.visibility = "hidden";
          p.style.transform = "translateY(10px)";
        }
      });
    }

    // Initialize state
    setStep("default");

    steps.forEach(el => {
      const stepNum = el.getAttribute("data-step");

      el.addEventListener("mouseenter", () => {
        if (root.getAttribute("data-active-step") !== "success") {
          setStep("step" + stepNum);
        }
      });

      el.addEventListener("mouseleave", () => {
        if (root.getAttribute("data-active-step") !== "success") {
          setStep("default");
        }
      });

      el.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setStep("step" + stepNum);
        }
      });
    });

    if (button) {
      button.addEventListener("click", () => {
        const current = root.getAttribute("data-active-step");
        if (current === "success") {
          setStep("default");
        } else {
          setStep("success");
        }
      });

      button.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          button.click();
        }
      });
    }
  }

  try {
    init();
  } catch(e) { console.error(e); }
  document.addEventListener("DOMContentLoaded", () => {
    try { init(); } catch(e) {}
  });
})();
